jwt-decoder.formula:
الرمز = base64url(الترويسة) + "." + base64url(الحمولة) + "." + base64url(التوقيع)
الترويسة: { "alg": "HS256", "typ": "JWT" }
الحمولة: { "sub": "1234567890", "name": "Asha", "iat": 1792281600, "exp": 1792368000 }
التوقيع: HMAC-SHA256(السر، header_b64 + "." + payload_b64)
فك الترميز: JSON.parse(base64urlDecode(الجزء))  // لا مفتاح لازم
التحقق: إعادة حساب التوقيع ومقارنة البايتات  // يلزم السر
